int snd_timer_user_select(struct file *file, struct snd_timer_select __user *_tselect)
{
    struct snd_timer_user *tu = file->private_data;
    struct snd_timer *timer;
    struct snd_timer_select tselect;
    struct snd_timer_id tid;
    int err;

    if (tu->timer) {
        snd_timer_free(tu->timer);
        tu->timer = NULL;
    }

    if (copy_from_user(&tselect, _tselect, sizeof(tselect)))
        return -EFAULT;

    snd_timer_id_to_native(&tselect.id, &tid);

    timer = snd_timer_new(&tid, "User Timer", SNDRV_TIMER_GLOBAL_FAST);
    if (!timer)
        return -ENOMEM;

    tu->timer = timer;
    tu->q = kmalloc(sizeof(*tu->q) * 2, GFP_KERNEL);
    if (!tu->q) {
        snd_timer_free(timer);
        tu->timer = NULL;
        return -ENOMEM;
    }

    timer->callback = snd_timer_user_callback;
    timer->private_free = snd_timer_user_free;
    timer->private_data = tu;

    return 0;
}

int select_and_init_timer(struct file *file, struct snd_timer_select __user *_tselect) {
    struct snd_timer *timer;
    struct snd_timer_select tselect;
    int err;

    if (copy_from_user(&tselect, _tselect, sizeof(tselect)))
        return -EFAULT;

    if (file->private_data) {
        snd_timer_close(file->private_data);
    }

    timer = snd_timer_new(&tselect.card, &tselect.id, 0);
    if (!timer)
        return -ENOMEM;

    file->private_data = timer;

    if (snd_timer_open(timer, &tselect, 0) < 0) {
        snd_timer_free(timer);
        return -EINVAL;
    }

    timer->flags |= SNDRV_TIMER_FLAG_FAST;
    timer->callback = snd_timer_gettime;
    timer->private_free = snd_timer_free;

    return 0;
}

int snd_timer_select(struct file *file, struct snd_timer_select __user *_tselect) {
    struct snd_timer *timer;
    struct snd_timer_select tselect;
    int err;

    if (copy_from_user(&tselect, _tselect, sizeof(tselect)))
        return -EFAULT;

    timer = snd_timer_new(file, &tselect);
    if (!timer)
        return -ENOMEM;

    if (timer->private_free)
        timer->private_free(timer);

    timer->flags |= SNDRV_TIMER_FLG_FAST;
    timer->callback = snd_timer_callback;
    timer->private_data = file->private_data;

    return 0;
}

int snd_timer_select(struct file *file, struct snd_timer_select __user *_tselect) {
    struct snd_timer *timer = file->private_data;
    struct snd_timer_select tselect;
    int err;

    if (timer) {
        snd_timer_close(file);
    }

    if (copy_from_user(&tselect, _tselect, sizeof(tselect))) {
        return -EFAULT;
    }

    timer = snd_timer_new(&tselect.card, &tselect.id, &tselect.info, NULL);
    if (!timer) {
        return -ENOMEM;
    }

    timer->private_data = file;

    if (tselect.info.queue_size) {
        struct snd_timer_queue *queue;
        queue = kmalloc(sizeof(*queue), GFP_KERNEL);
        if (!queue) {
            snd_timer_free(timer);
            return -ENOMEM;
        }
        timer->queue = queue;
    }

    timer->callback = snd_timer_callback;
    timer->private_free = snd_timer_free_private;
    timer->flags |= SNDRV_TIMER_FLG_FAST;

    file->private_data = timer;
    return 0;
}

int snd_timer_user_select(struct file *file, struct snd_timer_select __user *_tselect) {
    struct snd_timer_user *tu = file->private_data;
    struct snd_timer *timer;
    struct snd_timer_select tselect;
    int err;

    if (tu->timer) {
        snd_timer_close(tu->timer);
        tu->timer = NULL;
    }

    if (copy_from_user(&tselect, _tselect, sizeof(tselect)))
        return -EFAULT;

    timer = snd_timer_new(tselect.name, 0, &tselect, NULL);
    if (!timer)
        return -ENOMEM;

    tu->timer = timer;
    tu->timer->private_data = tu;

    if (snd_timer_user_init(tu->timer, tu) < 0) {
        snd_timer_close(tu->timer);
        tu->timer = NULL;
        return -ENOMEM;
    }

    tu->timer->callback = snd_timer_user_callback;
    tu->timer->private_free = snd_timer_user_free;
    tu->timer->flags |= SNDRV_TIMER_PCM_FAST;

    return 0;
}
